{"explanation":"A Riemann sum approximates the area under y = x² by adding rectangle areas: Σ f(xᵢ*)Δx, where Δx = 2/n. Use the slider to increase the number of rectangles, and drag the yellow point to change where each rectangle samples the curve—from left endpoints through midpoints to right endpoints. As n increases, the sum approaches the exact area, ∫₀² x² dx = 8/3.","manimCode":"let n = 6;
let sample = 0.5;
const ax = new Axes({ xRange: [-0.3, 2.3, 0.5], yRange: [-0.5, 4.5, 1], xLength: 7, yLength: 4.6, tips: false });
const curve = ax.plot(x => x * x, { xRange: [0, 2], color: BLUE });
const title = new Text({ text: 'Riemann sums: y = x²', fontSize: 30, color: WHITE });
title.moveTo([-2.1, 3.25, 0]);
const sumReadout = new Text({ text: '', fontSize: 25, color: TEAL });
sumReadout.moveTo([0, -2.65, 0]);
const exactReadout = new Text({ text: '', fontSize: 22, color: WHITE });
exactReadout.moveTo([0, -3.02, 0]);
const hint = new Text({ text: 'Drag yellow point: left → midpoint → right sampling', fontSize: 19, color: YELLOW });
hint.moveTo([0, -3.45, 0]);
const handle = new Dot({ point: ax.c2p(1.8, 3.24), radius: 0.13, color: YELLOW });
let rectangles = [];

function rebuildRectangles() {
  for (const rect of rectangles) scene.remove(rect);
  rectangles = [];
  for (let i = 0; i < n; i++) {
    const rect = new Polygon({ vertices: [ax.c2p(0, 0), ax.c2p(0.01, 0), ax.c2p(0.01, 0.01), ax.c2p(0, 0.01)], color: TEAL });
    rect.setFill(TEAL, 0.28);
    rect.setStrokeWidth(1.5);
    rectangles.push(rect);
    scene.add(rect);
  }
  scene.remove(curve, handle);
  scene.add(curve, handle);
}

function update() {
  const dx = 2 / n;
  let sum = 0;
  for (let i = 0; i < n; i++) {
    const left = i * dx;
    const right = (i + 1) * dx;
    const sampleX = left + sample * dx;
    const height = sampleX * sampleX;
    rectangles[i].setVertices([ax.c2p(left, 0), ax.c2p(right, 0), ax.c2p(right, height), ax.c2p(left, height)]);
    sum += height * dx;
  }
  const lastX = (n - 1 + sample) * dx;
  handle.moveTo(ax.c2p(lastX, lastX * lastX));
  const mode = sample < 0.001 ? 'Left endpoints' : sample > 0.999 ? 'Right endpoints' : Math.abs(sample - 0.5) < 0.015 ? 'Midpoints' : 'Sample position: ' + (100 * sample).toFixed(0) + '%';
  sumReadout.setText('n = ' + n + '   |   Δx = ' + dx.toFixed(3) + '   |   Sum = ' + sum.toFixed(5));
  exactReadout.setText(mode + '   •   Exact = 8/3 ≈ 2.66667   •   Error = ' + (sum - 8 / 3).toFixed(5));
}

scene.add(title, sumReadout, exactReadout, hint);
await scene.play(new Create(ax));
rebuildRectangles();
update();
await scene.play(new Create(curve));

makeDraggable(handle, scene, { onDrag: (mob, pos) => {
  const dx = 2 / n;
  const x = ax.pointToCoords(pos)[0];
  sample = Math.max(0, Math.min(1, (x - (n - 1) * dx) / dx));
  update();
} });

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'Rectangles n', min: 1, max: 60, value: n, step: 1, onChange: value => {
  n = Math.round(value);
  rebuildRectangles();
  update();
} });

await scene.wait(999999);"}

